input.command:
mkdir -p scratch/nineTailedKitsune && cat > scratch/nineTailedKitsune/run.ts <<'EOF'
import * as THREE from "three";
import build from "../../samples/nineTailedKitsune";
const root = build();
const box = new THREE.Box3().setFromObject(root, true);
let tris = 0, parts = 0;
root.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) { parts++; const g = m.geometry; tris += (g.index ? g.index.count : g.attributes.position.count) / 3; } });
let joints = 0; root.traverse((o) => { if (!(o as THREE.Mesh).isMesh) joints++; });
console.log("size", box.getSize(new THREE.Vector3()).toArray().map((x) => x.toFixed(2)), "min", box.min.toArray().map((x) => x.toFixed(3)), "parts", parts, "tris", tris, "nodes", joints);
EOF
npx tsx scratch/nineTailedKitsune/run.ts 2>&1 | tail -30
